const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
export async function openCover(){const cover=document.getElementById('intro');if(cover.hidden||reduced()||!cover.animate)return;const motion=cover.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-20px)',filter:'blur(6px)'}],{duration:430,easing:'cubic-bezier(.5,0,.2,1)',fill:'forwards'});try{await motion.finished;}finally{motion.cancel();}}
export function setupCover(){const cover=document.getElementById('intro');let frame=0;cover.addEventListener('pointermove',e=>{if(reduced()||e.pointerType==='touch'||cover.hidden)return;cancelAnimationFrame(frame);const r=cover.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;frame=requestAnimationFrame(()=>{cover.style.setProperty('--map-x',`${(x-.5)*16}px`);cover.style.setProperty('--map-y',`${(y-.5)*12}px`);});});cover.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);cover.style.setProperty('--map-x','0px');cover.style.setProperty('--map-y','0px');});}
